   "text": "It's well known that physical exercise is beneficial not just to physical health but also to mental health. Yet whereas most\ncountries have {26} evidence-backed guidelines on the type and intensity of exercise {27} for various physical\nhealth benefits, such guidelines do not yet exist for exercise and mood. This is {28} due to a lack of necessary evidence.\nHowever, a new systematic review brings us usefully up-to-date on the current findings in this area.\nBefore {29} into some of the key take -aways, an important {30} made in the review is between aerobic\nexercise and anaerobic. The former {31} such things as walking, jogging and cycling and means ex ercising in such a\nway that your body is able to use oxygen to burn fat for energy. In contrast, anaerobic exercise—such as lifting heavy\nweights—is of such {32} intensity that your body does not have time to use oxygen to create energy and so instead it\nbreaks down glucose (葡萄糖) in your blood or muscles.\nBeginning first with the influence of exercise intensity on the mood benefits of aerobic exercise, the researchers, led by\nJohn Chan at Shenzhen University, found {33} results from 19 relevant studies. Some favoured higher intensity, others\nlow, while seven studies found that intensity made no {34} to mood benefits.\nIn relation to the intensity of anaerobic exercise, however, the results were far clearer —the optimum ( 最佳选择) for\nimproving mood is {35} intensity, perhaps because low intensity is too dull while high intensity is too unpleasant.",
   "answers": {
    "26": "D",
    "27": "M",
    "28": "L",
    "29": "F",
    "30": "G",
    "31": "I",
    "32": "O",
    "33": "B",
    "34": "E",
    "35": "J"
   }
