  "translation": {
   "prompt": "中国的传统婚礼习俗历史悠久，从周朝开始就逐渐形成了一套完整的婚礼仪式，有些一直沿用至 今。如今的中式婚礼习俗已有很大变化，但婚礼庆典仍然十分隆重。婚礼场地经过精心装饰，以象征 喜 庆(jubilance) 的红色为主色调，摆放着许多祝愿新人幸福的物件。在婚礼上，新人要拜天地(bow to Heaven and Earth),拜父母和相互对拜，然后设宴招待宾客，并向宾客敬酒致谢。今天，许多年轻 人依然钟情于传统的中式婚礼，体验独特而美好的中国式浪漫。",
   "reference": "Traditional wedding customs inChina have a long history, andsince the Zhou Dynasty a complete setof wedding\nrituals has gradually developed, some ofwhich are still in use today. Nowadays, Chinese wedding customs have\n六级2024.6 第一套19\nchanged a lot, but the ceremony is still very grand. The wedding venue is carefully decorated, with the main color\nof red, a symbol of jubilance, and many objects areplaced to wish the couple happiness. At the wedding, the couple\nwill bow to Heaven and Earth, totheirparents and to eachother, and then hold a banquet to entertain the guests and\ntoast the guests to express their gratitude. Today, manyyoung people still preferthe traditional Chinese wedding, to\nexperiencetheunique and beautiful Chinese romance.\n·"
  }
