   "text": "A team of researchers led by Priyanka Joshi examined the degree to which men and women relied on “communicative\nabstraction” to verbally convey their ideas and emotions. Communicative abstraction, according to the researchers, reflects\nthe tendency of people to use “abstract speech that focuses on the broader picture and {26} purpose of action rather than\nconcrete speech focusing on details and the means of {27} action.” Interestingly, they found that men were far more\nlikely to speak in the abstract than were women.\nTo arrive at this {28} , the researchers examined the linguistic (语言的) patterns of men and women in over 600,000\nblog posts written on websites. To do this, the researchers computed abstractness ratings for {29} 40,000 commonly\nused words in the English language. Words considered to be concrete could be easily visualized such as “table” or “chair”.\nWords that were more {30} to visualize, for example, “justice” or “morality” were considered to be more abstract. They\nfound that men used {31} more abstract language in their blog posts.\nWhat is the {32} of this effect? The researchers suggest that power differences between the genders — that is, men\nhaving more power in society — might be a key determinant (决定因素) .For instance, in a follow-up study conducted with\na sample of {30} 0 students, the researchers {33} power dynamics in an interpersonal setting to see if this would influence\ncommunicative abstraction. They found that participants in a high -power interviewer role were more likely to give abstract\ndescriptions of behaviors than were participants in a low-power interviewee role. This suggests that communicating more\nabstractly does not reflect a {34} tendency of men or women but rather {35} within specific contexts.",
   "answers": {
    "26": "O",
    "27": "B",
    "28": "C",
    "29": "A",
    "30": "D",
    "31": "M",
    "32": "N",
    "33": "I",
    "34": "F",
    "35": "E"
   }
