    "text": "Questions 51 to 55 are based on the following passage.\nWhen someone asks us 'what do you do?'we nearly always reply with our occupation.Work,for many of us,is much more than a job.It is the defining aspect of our identity.For many of us it is through our job that we can define ourselves.\n“Without myjob I don't know who I am,”is a sentence that has been uttered on more than a handful of occasions from my office chair.Indeed,it can be one of the most challenging aspects I work on with clients who have lost or been forced into changing their jobs.This loss provokes an identity crisis much greater than the loss of thejob itself.\nOne of the things I have come to understand,however,is that our identity is much more complex than we recognise at first glance.If we take the time to reflect we might recognise that as well as our work we can also identify as a friend,a spouse,a sonor daughter,a parent,a member of a sports team or religious community.We may recognise that we feel and act differently in these roles and relationships than we do at work.The passive daughter becomes an assertive leader at work.Furthermore,our identities at work are not static.They change over time.I myself have been a shop assistant,a waitress,a student,a graduate,and a clinical psychologist.At each stage my ability to adapt to and develop my career identity has been crucial to my wellbeing.Whilst we like to eliminate uncertainty in our lives at some level we have to manage uncertainty,especially in today's volatile and ever-shifting job market.\nHow we see ourselves is central to the issue ofour identity.When we tell ourselves “I'm good at starting projects but not so great at seeing them through”it can become part ofour belief system.But if you have the unfortunate experience of an enforced job change you will need to examine those beliefs to see how grounded in reality they are.You will be required to ask yourself how helpful these beliefs are and consider personal change We can change our beliefs,behaviours and emotional experience at any time through experimentation,practice and conscious self-discipline.In an age where career progression may lead us into new sectors it is ever more important to challenge our sense of self and explore whether you can create a new experience ofyour identity by changing the beliefs you hold about yourself in orderto expand your career options.Ultimately it is you who define who you are.You are only your job ifyou let it be so.",
