    "text": "Questions 46 to 50 are based on the following passage.\nIt may sound surprising, but you don't have to be interested in fashion, or even in history, to enjoy Dress Codes: How\nthe Laws of Fashion Made History. I happen to be interested in both, and ended up enjoying the book for completely different\nreasons.\nRichard Thompson Ford is a law professor, and you probably won't forget that for even one page. His carefully reasoned\narguments, packed with examples, sound almost like reading a court opinion, only maybe wordier. You will probably never\nthink of fashion as a trifle again.\nFord's thesis is that the best way to understand what particular fashions meant in any given era is to look at the restrictions\nplaced on them. Through this lens, he shows us that the first laws passed in the 1200s to ensure that only the nobility were\nallowed to wear certain fabrics, colors and ornaments reflected the rise of the middle class, who were now able to imitate\nsome of these fashions. The status of the upper classes was threatened: fashion was a tool to preserve it.\nFord takes the reader through the evolution of fashion while examining the underlying motivations of status: sex, power,\nand personality, which, he assumes, influenced all innovations in fashion in the past and which continue to influence us today.\nHis writing is more than a little dense — dense with research, clauses, and precise adjectives and nouns. But there's also\nhumor and enough interesting episodes to make the writing appealing. No one is spared his sharp analysis: not the easy targets\nof 19th century women's crippling (伤害身体的) fashions nor the modern uniforms of Silicon Valley T-shirts.\nBut the greatest strength of this book (on fashion!) is its intellectual profoundness. Ford asks us to question unconscious\nbeliefs, to realize that we almost never do so, to understand that the simplest choices are charged with meaning, and yet that\nmeaning can and does change all the time. Consider the fact that a 1918 catalog insisted that boys and girls be dressed in the\nappropriate color. We believe our thinking today is evolved. Ford shows us it’s not.",
