  "writing": {
   "prompt": "Directions:For this part,you are allowed 30 minutes to write an essay that begins with the sentence“Nowadays cultivating independent learning ability is becoming increasingly crucial for personal development.”You\ncan make comments,cite examples or use your personal experiences to develop your essay.You should write at least 150 words but no more than 200 words.\nYou should copy the sentence given in quotes at thebeginning of your essay.",
   "model": "Nowadays, cultivating independent learning ability is becoming increasingly\ncrucial forpersonal development. In today's rapidlychanging world, only when we\nare active in learning independently can we keep pace with the times.1\nOn the one hand, independent learning allows us to explore our interests and\npassions at our own pace. This enhances our motivation to learn. It also encourages\nself-discipline and time management skills, both ofwhich are essential to our\npersonal development. On the other hand, independent learning is the key to\ndeveloping adaptability. In this ever-changing society, we often face unforeseen\nchallenges. Independent learning enables us to find propersolutions in time, which\nplays a key role on our roadto success. Furthermore, independent learning is crucial\nfor fostering critical thinking. Independent learners can question, evaluate, and\nassimilate information effectively. This not only enhances ourunderstanding of novel\nthings but also promotes ourcreativity and innovation ability.2\nTo sum up, there is no doubt that independent learning ability plays a crucia\nrole in our personal development. It equips us with the strong ability to adapt to the\ncomplex modern life,3\n1 发表个人观点，指出只有\n积极主动地自主学习才能\n跟上时代的步伐。\n2分别从“自主学习使我们\n按照自己的节奏探索自己\n的兴趣和爱好”“自主\n学习是发展适应能力的关\n键”和“自主学习对于培\n养批判性思维至关重要”\n三个方面论证自主学习\n的重要性，由连接词On\nthe one hand、On the other\nhand和Furthermore引出。\n3 总结全文，强调自主学习\n能力的重要性。\n·"
  },
  "listening": null,
