    "text": "Questions 51 to 55 are based on the following passage.\nThe traditional school year, with three months of vacation every summer, was first implemented\nwhen America was an agricultural society and the summer months were needed for farm work. Since then,\nwe've completely changed as a nation. Students no longer spend summers farming, but they aren't in\nschool, either. The average American student receives 13 weeks off from school each calendar year—with\nabout 11 of those during the summer. Few other countries have more than seven weeks off in a school\ncalendar.\nWith the U.S. lagging behind other countries in academics, it's time to consider year-round schooling.\nOne benefit of this change is that students will not fall victim to the \"summer slide,\" or the well-\ndocumented phenomenon where students forget some of the knowledge they have acquired when too much\ntime is taken off from school. Decades of research shows that it can take from 8 to 13 weeks at the\nbeginning of every school year for students to get back to where they were before the summer holiday.\nBut year-round schooling isn't just about academics. Teachers and students experience a closer\nrelationship in year-round schools than they do in traditional schools and, in the absence of any long-term\nbreak, students do not feel detached from the school environment. These closer bonds and greater\nattachment pay off. Research shows that students in year-round schools are more self-confident and feel\nmore positive about their schooling experience.\n第7页,共8页\nBut don't kids need time to relax? Some childhood development experts believe that time off from\nschool is vital to healthy development as kids are not designed to spend so much of their time inside\nclassrooms and the summer break provides a perfect opportunity to get outside. The problem with this\nargument is that most children aren't playing outside or even spending time with other kids. While some\nchildren visit summer camps, most stay at home, watching TV or playing games on electronic devices,\nwhich hardly benefits them.\nThe U.S. has changed from a farming economy to a knowledge- and innovation-based economy, so it\nmakes sense for the school year to change as well.",
