   "text": "You may not use any of the words\nin the bank more than once.\nWhether you're just having a down day or a down period, taking a walk can instantly lift your mood,\nespecially when you go outdoors. Not only can walking make you less depressed, but according to a new\nstudy, depression sufferers who took a {26} walk showed just as much improvement in their {27} as\npeople taking medicine. In fact, 60-70 percent of the participants in the study could no longer even be {28} as depressed.\nBone density may not be one of the most exciting health benefits of walking, but it's an important\none. People with stronger bones avoid osteoporosis(骨质疏松症)and all the problems that {29} with it,\nlike breaks and other disabilities. And the best way to get strong, healthy bones is by doing weight-bearing\nexercises like running, dancing and walking,according to a large study. But as regards bones, it's {30} use it or lose it: To keep your bones strong you have to keep exercising. The researchers found that adults\nwho walked regularly had better bone density throughout their lives than their {31} friends.\nTaking a walk can be great for {32} your head or blowing off some steam.It also provides a great\nopportunity to {33} with friends and family, far away from electronics and other {34} at home. Even\nbetter, you set a powerful example because when they see you {35} the benefits of walking, they'll be\nencouraged to walk more, too.",
