    "text": "Questions 46 to 50 are based on the following passage.\nTeam-building exercises have become popular for managers trying to increase organisational and team\nharmony and productivity. Unfortunately many employees resent compulsory bonding and often regard\nthese exercises as a nuisance.\nA paper published this week by University of Sydney researchers in Social Networks has reported\nparticipants' feelings about team-building interventions(干预),revealing ethical implications in forcing\nemployees to take part.\n\"Many people see team-building activities as a waste of time, so we decided to look in more depth at\nwhat's behind this,\" said the paper's lead researcher, Dr Peter Matous.\n\"Teams are formed, combined and restructured. Staff are relocated and office spaces redesigned. All\nthis is done with the aim of improving workplace efficiency, collaboration and cohesion. But does any of\nthis work?\" said Dr Matous.\nThe study found that team-building exercises which focused on the sharing of and intervening into\npersonal attitudes and relationships between team members were considered too heavy-handed and\nintrusive, although the researchers say some degree of openness and vulnerability is often necessary to\nmake deep, effective connections with colleagues.\n\"Some participants were against team-building exercises because they were implicitly compulsory.\nThey didn't welcome management's interest in their lives beyond their direct work performance,\" said\nMatous.\"Many people don't want to be forced into having fun or making friends, especially not on top of\ntheir busy jobs. They feel management is being too nosy or trying to control their lives too much.”\nIn this study the researchers recommended a self-disclosure(表露)approach where participants were\nguided through a series of questions that allowed them to increasingly disclose personal information and\nvalues. The method is well-tested and has been shown to increase interpersonal closeness. However, to be\nsuccessful it must be voluntary.\nThe researchers said there are numerous schools of thought that propose differing psychological\nmethods for strengthening relationships.\"With caution, many relational methods to improve teams and\norganisations can be borrowed from other fields. The question is how to apply them effectively to\nstrengthen an entire collective, which is more than just the sum of individual relationships,” said\nDr Matous.",
