  "translation": {
   "prompt": "中国政府一直大力推行义务教育(compulsory education),以使每个儿童都享有受教育的机会。\n自1986年《义务教育法》生效以来，经过不懈努力，实现了在全国推行义务教育的目标。如今，在中国，儿童年满六周岁开始上小学，从小学到初中一共接受九年义务教育。从2008年秋季学期开始，义务教育阶段学生无须缴纳学费。随着一系列教育改革举措的实施，中国义务教育的质量也有显著提高。\n第6页,共6页",
   "reference": "无论你是某天心情不好还是某段时间心情不好 ， 散步都能立刻改善你的情绪 ， 尤其是在户外散步 。 散步不仅可以缓解你的抑郁 ， 而且根据一项新的研究 ， 每天散步的抑郁症患者的症状改善程度和吃药的人一样 。 事实上 ， 这个研究中有 60 ％ 到 70 ％ 的参与者甚至不再被界定为抑郁症患者 。 骨密度可能不是散步最令人兴奋的健康益处之一 ， 但它是一个重要的好处 。 骨骼强壮的人可以避免骨质疏松症和随之而来的所有问题 ， 比如骨折和其他残疾 。 一项大型研究表明 ， 获得强壮 、 健康骨骼的最佳方式是进行诸如跑步 、 跳舞和散步等负重运动 。 但就骨骼而言 ， 它绝对是用进废退 ： 为了保持骨骼强壮 ， 你必须坚持锻炼 。 研究人员发现 ， 经常走路的成年人一生的骨密度要比他们不怎么活动的朋友高 。 散步可以很好地清理你的头脑或释放压力 。 它还提供了一个与朋友和家人建立联系的好机会 ， 能够远离电子产品和家里的其他干扰 。 更好的是 ， 你树立了一个强有力的榜样 ， 因为当他们看到你从散步中获益时 ， 他们也会受到鼓励 ， 愿意多走路 。\n===PAGE 4===\nSection B 〖 文章来源 〗 本文选自 2017 年 1 月 22 日发表在 （ 《 纽约时报 》 官网 ） 上一篇标题为 “ A Club Where Lions Dance and Traditions Take R t ” （ 《 一个舞狮和传统扎根的俱乐部 》 ） 的文章 。 〖 结构框图 〗 A ） 一 D ） 段介绍了这家俱乐部的起源 、 发展 、 成员组成等情况 。 本文主要介绍了一家在曼哈顿的致力于通一 0 E ） 一 G ） 段介绍了舞狮的起源 、 如何舞狮以及舞狮的意义 。 过舞狮传承中国传统文化的舞狮俱乐部 。 一 H ） 一 L ） 段介绍了俱乐部不同成员对舞的看法 。"
  },
